opts = {
 "1": (lambda t,s: 3*t*(math.exp(s)-1), lambda t,s: t/2*(math.exp(-s)+1), lambda t,s: t*t*math.exp(-2*s)),
 "2": (lambda t,s: 2*t*(math.exp(s)-1), lambda t,s: t*(2*math.exp(2*s)-1), lambda t,s: t*t/2*(1+math.exp(-2*s))),
 "3": (lambda t,s: 2*t*(math.exp(s)-1), lambda t,s: t/2*(math.exp(s)+1), lambda t,s: t*t*math.exp(2*s)),
 "4": (lambda t,s: t*(math.exp(-s)-1), lambda t,s: -2*t*(math.exp(-s)-1.5), lambda t,s: t*t*(2*math.exp(-2*s)-1)),
}

h = 1e-5
def d(f, t, s):
    return (f(t, s+h) - f(t, s-h)) / (2*h)

def check(name):
    X, Y, U = opts[name]
    ok = True
    for t in (-1.7, 0.5, 2.3):
        # initial curve: x=0, y=t, u=t^2 at s=0
        if abs(X(t,0)) > 1e-9 or abs(Y(t,0)-t) > 1e-9 or abs(U(t,0)-t*t) > 1e-9:
            ok = False
        for s in (-0.7, 0.0, 0.4, 1.1):
            q = d(X, t, s)   # dx/ds = F_p = q
            p = d(Y, t, s)   # dy/ds = F_q = p
            du = d(U, t, s)  # du/ds = p F_p + q F_q = 2pq
            u = U(t, s)
            tol = 1e-4 * (1 + abs(u))
            if abs(p*q - u) > tol or abs(du - 2*p*q) > tol:
                ok = False
        # initial p,q consistency: u_tau = q*y_tau => q0 = 2t, p0 = t/2
        q0 = d(X, t, 0.0); p0 = d(Y, t, 0.0)
        if abs(q0 - 2*t) > 1e-4 or abs(p0 - t/2) > 1e-4:
            ok = False
    return ok

res = {k: check(k) for k in opts}
good = [k for k, v in res.items() if v]
if len(good) == 1:
    ans = "Option " + good[0]
else:
    ans = "UNSUPPORTED"
print(json.dumps({"final_answer": ans, "evidence": {"checks": res,
      "derivation": "q0=2t,p0=t/2; x=2t(e^s-1), y=t/2(e^s+1), u=t^2 e^{2s}"}}))
