# parse
segs = []
for part in re.split(r'(?=M)', path):
    nums = re.findall(r'-?\d+\.?\d*', part)
    pts = [(float(nums[i]), float(nums[i+1])) for i in range(0, len(nums), 2)]
    for i in range(len(pts)-1):
        segs.append((pts[i], pts[i+1]))

EPS = 1e-4
verts = []
def vid(p):
    for i, q in enumerate(verts):
        if abs(p[0]-q[0]) < EPS*10 and abs(p[1]-q[1]) < EPS*10:
            return i
    verts.append(p)
    return len(verts)-1

for a, b in segs:
    vid(a); vid(b)

def cross(a, b): return a[0]*b[1]-a[1]*b[0]

# intersections
extra = [[] for _ in segs]
for i, (a, b) in enumerate(segs):
    d = (b[0]-a[0], b[1]-a[1])
    L2 = d[0]**2+d[1]**2
    for p in list(verts):
        t = ((p[0]-a[0])*d[0]+(p[1]-a[1])*d[1])/L2
        if 1e-6 < t < 1-1e-6:
            q = (a[0]+t*d[0], a[1]+t*d[1])
            if math.hypot(q[0]-p[0], q[1]-p[1]) < EPS*5:
                extra[i].append(t)
    for j, (c, e) in enumerate(segs):
        if j <= i: continue
        d2 = (e[0]-c[0], e[1]-c[1])
        den = cross(d, d2)
        if abs(den) < 1e-12: continue
        w = (c[0]-a[0], c[1]-a[1])
        t = cross(w, d2)/den
        u = cross(w, d)/den
        if 1e-6 < t < 1-1e-6 and 1e-6 < u < 1-1e-6:
            p = (a[0]+t*d[0], a[1]+t*d[1])
            vid(p)
            extra[i].append(t)
            extra[j].append(u)

edges = set()
for i, (a, b) in enumerate(segs):
    d = (b[0]-a[0], b[1]-a[1])
    ts = sorted(set([0.0, 1.0] + extra[i]))
    ids = []
    for t in ts:
        p = (a[0]+t*d[0], a[1]+t*d[1])
        v = vid(p)
        if not ids or ids[-1] != v:
            ids.append(v)
    for k in range(len(ids)-1):
        if ids[k] != ids[k+1]:
            edges.add((min(ids[k], ids[k+1]), max(ids[k], ids[k+1])))

n = len(verts)
adj = [[] for _ in range(n)]
for a, b in edges:
    adj[a].append(b); adj[b].append(a)

cycles = []
def dfs(s, cur, path, visited):
    for nb in adj[cur]:
        if nb == s and len(path) >= 3 and path[1] < path[-1]:
            cycles.append(list(path))
        elif nb > s and nb not in visited:
            visited.add(nb); path.append(nb)
            dfs(s, nb, path, visited)
            path.pop(); visited.discard(nb)
for s in range(n):
    dfs(s, s, [s], {s})

def inside(pt, poly):
    x, y = pt
    c = False
    m = len(poly)
    for i in range(m):
        x1, y1 = poly[i]; x2, y2 = poly[(i+1) % m]
        if (y1 > y) != (y2 > y):
            xi = x1+(y-y1)*(x2-x1)/(y2-y1)
            if xi > x: c = not c
    return c

def onboundary(pt, poly):
    m = len(poly)
    for i in range(m):
        a = poly[i]; b = poly[(i+1) % m]
        d = (b[0]-a[0], b[1]-a[1])
        L = math.hypot(*d)
        if abs(cross(d, (pt[0]-a[0], pt[1]-a[1])))/L < 1e-3:
            t = ((pt[0]-a[0])*d[0]+(pt[1]-a[1])*d[1])/L**2
            if -1e-6 <= t <= 1+1e-6: return True
    return False

found = {}
for cyc in cycles:
    P = [verts[v] for v in cyc]
    m = len(P)
    # simplify collinear
    keep = []
    for i in range(m):
        a = P[i-1]; b = P[i]; c = P[(i+1) % m]
        u = (b[0]-a[0], b[1]-a[1]); w = (c[0]-b[0], c[1]-b[1])
        cr = cross(u, w)/(math.hypot(*u)*math.hypot(*w))
        if abs(cr) > 1e-3:
            keep.append(b)
    k = len(keep)
    if k < 3 or k > 6: continue
    # no interior edges
    bad = False
    for a, b in edges:
        mid = ((verts[a][0]+verts[b][0])/2, (verts[a][1]+verts[b][1])/2)
        if not onboundary(mid, P) and inside(mid, P):
            bad = True; break
    if bad: continue
    sides = [(keep[(i+1) % k][0]-keep[i][0], keep[(i+1) % k][1]-keep[i][1]) for i in range(k)]
    lens = [math.hypot(*s) for s in sides]
    def par(s, t): return abs(cross(s, t))/(math.hypot(*s)*math.hypot(*t)) < 1e-3
    def perp(s, t): return abs(s[0]*t[0]+s[1]*t[1])/(math.hypot(*s)*math.hypot(*t)) < 1e-3
    shape = None
    if k == 3:
        right = any(perp(sides[i], sides[(i+1) % 3]) for i in range(3))
        shape = 4 if right else 3
    elif k == 4:
        p1 = par(sides[0], sides[2]); p2 = par(sides[1], sides[3])
        if p1 and p2:
            if perp(sides[0], sides[1]):
                shape = 2 if abs(lens[0]-lens[1]) < 1e-3*lens[0] else 1
            else:
                shape = 5
        elif p1 or p2:
            shape = 6
    else:
        crs = [cross(sides[i], sides[(i+1) % k]) for i in range(k)]
        convex = all(c > 0 for c in crs) or all(c < 0 for c in crs)
        angs = []
        for i in range(k):
            s, t = sides[i], sides[(i+1) % k]
            angs.append(math.atan2(abs(cross(s, t)), s[0]*t[0]+s[1]*t[1]))
        regular = convex and (max(lens)-min(lens) < 0.01*max(lens)) and (max(angs)-min(angs) < 0.02)
        if k == 5:
            shape = 9 if regular else (7 if convex else 8)
        elif k == 6 and regular:
            shape = 10
    if shape:
        found.setdefault(shape, []).append(keep)

fs = set(found)
options = {
 'A': {1,7,3}, 'B': {1,8}, 'C': {7,9}, 'D': {5}, 'E': {1,5,7,8}, 'F': {1,5,7,8,4,6},
 'G': {7,8,2,10}, 'H': {1,8,9}, 'I': {5,3}, 'J': {1}, 'K': {7,8}, 'L': {5,8},
 'M': {5,2}, 'N': {1,8,2,4,9}, 'O': {1,5,7,8,10}, 'P': {1,7,8,6}}
ans = [k for k, v in options.items() if v == fs]
if len(ans) == 1:
    print(json.dumps({"final_answer": ans[0], "shapes_found": sorted(fs), "num_cycles": len(cycles)}))
else:
    print("UNSUPPORTED")
