def on_seg(p, a, b, tol=1e-3):
    if p == a or p == b:
        return False
    cr = (b[0]-a[0])*(p[1]-a[1]) - (b[1]-a[1])*(p[0]-a[0])
    L = math.dist(a, b)
    if abs(cr) / L > tol:
        return False
    d = ((p[0]-a[0])*(b[0]-a[0]) + (p[1]-a[1])*(b[1]-a[1])) / (L*L)
    return 0 < d < 1

