    cr = [vec[i][0]*vec[(i+1) % n][1]-vec[i][1]*vec[(i+1) % n][0] for i in range(n)]
    dt = [vec[i][0]*vec[(i+1) % n][0]+vec[i][1]*vec[(i+1) % n][1] for i in range(n)]
    convex = all(c > 0 for c in cr) or all(c < 0 for c in cr)
    ang = [math.atan2(abs(cr[i]), dt[i]) for i in range(n)]
    def par(i, j):
        return abs(vec[i][0]*vec[j][1]-vec[i][1]*vec[j][0]) / (ln[i]*ln[j]) < 0.01
    if n == 3:
        right = any(abs(dt[i]) / (ln[i]*ln[(i+1) % 3]) < 0.01 for i in range(3))
        return 4 if right else 3
    if n == 4:
        if not convex: return None
        p02, p13 = par(0, 2), par(1, 3)
        if p02 and p13:
            right = abs(dt[0]) / (ln[0]*ln[1]) < 0.01
            if right:
                return 2 if close(ln[0], ln[1]) else 1
            return 5 if not close(ln[0], ln[1]) or True else None  # parallelogram/rhombus
        if p02 != p13:
            return 6
        return None
    if n == 5:
        if not convex: return 8
        reg = all(close(ln[0], l) for l in ln) and all(close(ang[0], a) for a in ang)
        return 9 if reg else 7
    if n == 6:
        if convex and all(close(ln[0], l) for l in ln) and all(close(ang[0], a) for a in ang):
